/* K56flex's rate tables (modem/k56tab, generated by tools/gen_k56_tables.py;
 * docs/history/k56-facts.md, "Tables", "Data"). Against the facts: K, u, r
 * and M per pad of every rate, the frame identity, M^8 >= 2^K; each ring
 * list a permutation of the groups, each constellation M << (u - 1) mu-law
 * magnitude indices without repeats; the values the facts quote. */
#include <string.h>
#include "test.h"
#include "k56tab.h"

/* "Tables", per rate code r = 1..13 (R = 30000 + 2000 r) */
static const uint8_t f_K[13] = { 28, 30, 24, 26, 26, 28, 30, 24, 25, 27, 29, 31, 25 };
static const uint8_t f_u[13] = { 1, 1, 2, 2, 2, 2, 2, 3, 3, 3, 3, 3, 4 };
static const uint8_t f_r[13] = { 2, 2, 2, 2, 4, 4, 4, 4, 8, 8, 8, 8, 8 };
static const uint8_t f_M[3][13] = {
    { 13, 15, 9, 11, 11, 13, 15, 9, 10, 11, 13, 16, 9 },
    { 13, 15, 9, 11, 11, 13, 15, 9, 10, 11, 14, 16, 10 },
    { 13, 15, 9, 11, 11, 13, 15, 9, 10, 11, 13, 16, 10 },
};

int main(void)
{
    int r, pad, k, total_ring = 0, total_bios = 0;

    for (r = 1; r <= 13; r++) {
        const k56_rate_t *t = &k56_rates[r - 1];
        CHECK_EQ_I(t->K, f_K[r - 1]);
        CHECK_EQ_I(t->u, f_u[r - 1]);
        CHECK_EQ_I(t->r, f_r[r - 1]);
        CHECK(t->K + 8 * (t->u - 1) + 8 - 8 / t->r == 30 + 2 * r);   /* R / 1000 */
        for (pad = 0; pad < 3; pad++) {
            int M = t->M[pad], n = M << (t->u - 1);
            const uint8_t *ring = k56_ring(r, pad), *bios = k56_bios(r, pad);
            uint8_t seen[128];
            double m8 = 1.0;
            CHECK_EQ_I(M, f_M[pad][r - 1]);
            for (k = 0; k < 8; k++)
                m8 *= M;
            CHECK(m8 >= (double)(1UL << t->K));
            /* the ring list: a permutation of 0 .. M - 1 */
            memset(seen, 0, sizeof seen);
            for (k = 0; k < M; k++) {
                CHECK(ring[k] < M);
                if (ring[k] < M)
                    CHECK(!seen[ring[k]]++);
            }
            /* the constellation: n magnitude indices, each <= 127, no two equal */
            memset(seen, 0, sizeof seen);
            for (k = 0; k < n; k++) {
                CHECK(bios[k] <= 127);
                if (bios[k] <= 127)
                    CHECK(!seen[bios[k]]++);
            }
            total_ring += M;
            total_bios += n;
        }
    }
    CHECK_EQ_I(total_ring, 468);    /* the spec's 39 ring lists, 468 octets */
    CHECK_EQ_I(total_bios, 1382);   /* and 39 constellations, 1382 octets */

    CHECK(k56_rates[0].K == 28 && k56_rates[12].K == 25 && k56_rates[12].u == 4);
    CHECK(k56_rates[11].M[0] == 16 && k56_rates[10].M[1] == 14 && k56_rates[12].M[1] == 10);
    /* "Tables": 32000 with no pad, the ring list 2 3 4 5 6 7 1 8 0 10 9 11 12 */
    {
        static const uint8_t ring32[13] = { 2, 3, 4, 5, 6, 7, 1, 8, 0, 10, 9, 11, 12 };
        CHECK(memcmp(k56_ring(1, 0), ring32, sizeof ring32) == 0);
    }
    CHECK(k56_bios(13, 0)[0] == 3 && k56_bios(13, 0)[1] == 8);   /* 56000, no pad: 3, 8, 12, 16, 18 ... 101 */
    CHECK(k56_bios(13, 0)[2] == 12 && k56_bios(13, 0)[3] == 16 && k56_bios(13, 0)[4] == 18);
    CHECK(k56_bios(13, 0)[71] == 101);

    T_REPORT("test_k56tab");
}
